/* Painted fantasy VFX atlas — generated artwork; shared by the motion demo.
   2x2 cells: guard / spell projectile / crystal impact / Lilith ultimate.
   Image kept independent of character art for easy reuse and animation. */
(function(){
  'use strict';
  const atlas=new Image();
  atlas.decoding='async';
  atlas.src='data:image/webp;base64,';
  window.paintedFX=function(ctx,kind,x,y,w,h,opacity=1,rotate=0){
    if(!atlas.complete||!atlas.naturalWidth||opacity<=0)return;
    const cell={
      guard:[0,0], bolt:[1,0], burst:[0,1], ultimate:[1,1]
    }[kind];
    if(!cell)return;
    const sw=atlas.naturalWidth/2,sh=atlas.naturalHeight/2;
    ctx.save();
    ctx.globalAlpha=Math.max(0,Math.min(1,opacity));
    ctx.globalCompositeOperation='screen';
    ctx.translate(x,y);
    ctx.rotate(rotate);
    ctx.drawImage(atlas,cell[0]*sw,cell[1]*sh,sw,sh,-w/2,-h/2,w,h);
    ctx.restore();
  };
  window.PAINTED_VFX_READY=()=>atlas.complete&&atlas.naturalWidth>0;
})();